<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminGalleryService;
final class AdminGalleryController{public function __construct(private AdminGalleryService$s){}public function index(){return$this->run(fn()=>$this->s->data((int)auth()->id()));}public function realtimeVersion(){return$this->run(fn()=>$this->s->realtimeVersion((int)auth()->id()));}public function store(){return$this->run(fn()=>$this->s->store((int)auth()->id(),$_POST,$_FILES['file']??[]),201);}public function update(int$id){return$this->run(fn()=>$this->s->update((int)auth()->id(),$id,$_POST,$_FILES['file']??[]));}public function delete(int$id){return$this->run(function()use($id){$this->s->delete((int)auth()->id(),$id);return null;});}private function run(callable$f,int$status=200){try{return ResponseFactory::json(['success'=>true,'data'=>$f()],$status);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
